const payload = $input.first().json || {};
const workflowName = payload.workflow?.name || 'Unknown Workflow';
const failedNode = payload.execution?.lastNodeExecuted || 'Unknown Node';
const errorMessage = payload.execution?.error?.message || 'Unspecified execution error';
const executionUrl = payload.execution?.url || '';
const occurredAt = new Date().toISOString();

const alertRecord = {
  level: 'ERROR',
  service: 'lendloop-n8n-error-handler',
  workflowName,
  failedNode,
  errorMessage,
  executionUrl,
  occurredAt
};

console.error(JSON.stringify(alertRecord));

return [{ json: alertRecord }];

const alert = $input.first().json;
console.log(JSON.stringify({
  channel: 'admin_error_alert',
  subject: `[LendLoop Alert] Workflow Failure in ${alert.workflowName}`,
  body: `Workflow: ${alert.workflowName}\nNode: ${alert.failedNode}\nError: ${alert.errorMessage}\nTimestamp: ${alert.occurredAt}`
}));
return [{ json: { ...alert, adminNotified: true } }];
